css:
.print-format { padding: 0; max-width: 80mm; font-size: 12px; }
.kiosk-slip p { margin: 0 0 4px; }
.kiosk-slip__place, .kiosk-slip__label, .kiosk-slip__meta, .kiosk-slip__pay, .kiosk-slip__center { text-align: center; }
.kiosk-slip__place { font-size: 14px; font-weight: 600; }
.kiosk-slip__label { margin-top: 8px !important; text-transform: uppercase; letter-spacing: 0.08em; }
.kiosk-slip__number { text-align: center; font-size: 44px; font-weight: 700; line-height: 1.1; }
.kiosk-slip__items { width: 100%; margin: 8px 0; border-top: 1px dashed #000; border-bottom: 1px dashed #000; }
.kiosk-slip__items td { padding: 3px 0; vertical-align: top; }
.kiosk-slip__qty { width: 2.5em; }
.kiosk-slip__amount { text-align: right; white-space: nowrap; }
.kiosk-slip__addon td { padding-top: 0; }
.kiosk-slip__detail { font-size: 11px; color: #444; }
.kiosk-slip__total { display: flex; justify-content: space-between; font-size: 15px; font-weight: 700; }
.kiosk-slip__pay { margin-top: 10px !important; font-size: 16px; font-weight: 700; }

html:
{%- set session = frappe.db.get_value("Restaurant Session", doc.vunapos_restaurant_session, ["order_number", "kiosk_status"], as_dict=True) if doc.vunapos_restaurant_session else None -%}
{%- set place = frappe.db.get_value("Restaurant", doc.vunapos_restaurant, "restaurant_name") if doc.vunapos_restaurant else None -%}
{%- set table = frappe.db.get_value("Restaurant Table", doc.vunapos_restaurant_table, "table_label") if doc.vunapos_restaurant_table else None -%}
<div class="kiosk-slip">
	<p class="kiosk-slip__place">{{ place or doc.company }}</p>
	{%- if session and session.order_number %}
	<p class="kiosk-slip__label">{{ _("Order") }}</p>
	<p class="kiosk-slip__number">{{ session.order_number }}</p>
	{%- endif %}
	<p class="kiosk-slip__meta">
		{{ doc.vunapos_service_type or "" }}{% if table %} &middot; {{ _("Table") }} {{ table }}{% endif %}
	</p>
	<p class="kiosk-slip__meta">{{ frappe.utils.format_datetime(doc.vunapos_opened_at or doc.creation, "d MMM yyyy, HH:mm") }}</p>
	<table class="kiosk-slip__items">
		{%- for row in doc.items %}
		<tr class="{{ 'kiosk-slip__addon' if row.vunapos_parent_line_id else '' }}">
			<td class="kiosk-slip__qty">{{ "%g"|format(row.qty) }}&times;</td>
			<td>
				{{ ("+ " if row.vunapos_parent_line_id else "") ~ row.item_name }}
				{%- for choice in frappe.utils.parse_json(row.vunapos_modifiers or "[]") if not choice.addon_item %}
				<div class="kiosk-slip__detail">{{ choice.label }}</div>
				{%- endfor %}
				{%- if row.vunapos_item_note and not row.vunapos_parent_line_id %}
				<div class="kiosk-slip__detail">{{ row.vunapos_item_note }}</div>
				{%- endif %}
			</td>
			<td class="kiosk-slip__amount">{{ row.get_formatted("amount", doc) }}</td>
		</tr>
		{%- endfor %}
	</table>
	{%- if doc.vunapos_order_note %}
	<p class="kiosk-slip__detail">{{ doc.vunapos_order_note }}</p>
	{%- endif %}
	<p class="kiosk-slip__total">
		<span>{{ _("Total") }}</span>
		<span>{{ doc.get_formatted("rounded_total" if doc.rounded_total else "grand_total") }}</span>
	</p>
	{%- if session and session.kiosk_status == "Awaiting Payment" %}
	<p class="kiosk-slip__pay">{{ _("Please pay at the counter") }}</p>
	<p class="kiosk-slip__detail kiosk-slip__center">{{ _("Your order goes to the kitchen once you have paid.") }}</p>
	{%- else %}
	<p class="kiosk-slip__pay">{{ _("Your order is with the kitchen") }}</p>
	<p class="kiosk-slip__detail kiosk-slip__center">{{ _("Please pay at the counter before you leave.") }}</p>
	{%- endif %}
</div>
